from __future__ import annotations

import argparse
import csv
import hashlib
import json
import shutil
from pathlib import Path
from typing import Any

from docx import Document


FRONT5 = {
    "01": ("可见毛孔", "IMPLEMENTED_AND_REPORTED", "正式评分不变；医生九分区与大毛孔真实比例仍为GAP"),
    "02": ("油脂分泌倾向", "PARTIAL", "检测指标已报告；历史ECDF和正式等级未建立"),
    "03": ("综合色素", "PARTIAL", "五类结果分开报告；医生十医学分区尚未完整形成"),
    "04": ("弥漫性泛红", "PARTIAL", "正式评分已报告；痤疮和候选血管尚未进入正式排除链"),
    "05": ("血管样结构", "PARTIAL", "候选算法结果已报告；正式参考分布和评分未建立"),
}


def _load(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _json_in(folder: Path, suffix: str) -> Path:
    matches = list(folder.glob(f"*{suffix}"))
    if len(matches) != 1:
        raise RuntimeError(f"{folder} 期望1个 {suffix}，实际{len(matches)}个")
    return matches[0]


def _modules(document: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {row["模块编号"]: row for row in document["检测模块"]}


def _text(path: Path) -> str:
    doc = Document(path)
    values = [paragraph.text for paragraph in doc.paragraphs]
    values.extend(cell.text for table in doc.tables for row in table.rows for cell in row.cells)
    return "\n".join(values)


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _score(module: dict[str, Any]) -> Any:
    return module.get("综合得分")


def _shadow(module: dict[str, Any]) -> Any:
    return (module.get("V0.1.2_shadow对照") or {}).get("score")


def _common_metric_changes(old: dict[str, Any], new: dict[str, Any]) -> list[dict[str, Any]]:
    changes = []
    for module_id in FRONT5:
        old_metrics = {row.get("name"): row.get("value") for row in old[module_id].get("核心指标", [])}
        new_metrics = {row.get("name"): row.get("value") for row in new[module_id].get("核心指标", [])}
        for name in sorted(old_metrics.keys() & new_metrics.keys()):
            if old_metrics[name] != new_metrics[name]:
                changes.append({"module_id": module_id, "metric": name, "old": old_metrics[name], "new": new_metrics[name]})
    return changes


def _write_csv(path: Path, rows: list[dict[str, Any]]) -> None:
    if not rows:
        raise RuntimeError(f"拒绝写空CSV: {path}")
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
        writer.writeheader(); writer.writerows(rows)


def main() -> None:
    parser = argparse.ArgumentParser(description="V0.1.2前五项医学报告完整性QC")
    parser.add_argument("--baseline", type=Path, required=True)
    parser.add_argument("--current", type=Path, required=True)
    parser.add_argument("--candidate-root", type=Path, required=True)
    parser.add_argument("--coverage-doc", type=Path, required=True)
    args = parser.parse_args()

    baseline_names = {path.name for path in args.baseline.iterdir() if path.is_dir()}
    current_names = {path.name for path in args.current.iterdir() if path.is_dir()}
    if baseline_names != current_names or len(current_names) != 13:
        raise RuntimeError(f"13张样本集合不一致: baseline={len(baseline_names)} current={len(current_names)}")

    score_changes: list[dict[str, Any]] = []
    shadow_changes: list[dict[str, Any]] = []
    metric_changes: list[dict[str, Any]] = []
    coverage_rows: list[dict[str, Any]] = []
    visual_rows: list[dict[str, Any]] = []
    banned_user = ("official_v011_full_reference", "shadow_v012", "reference_not_ready", "candidate_algorithm", "engineering_default_equal_v1")
    banned_all = ("null分", "None分", "负担负担", "在Word中更新目录后显示页码")

    for sample in sorted(current_names):
        old_dir, new_dir = args.baseline / sample, args.current / sample
        old_doc = _load(_json_in(old_dir, "结构化数据.json")); new_doc = _load(_json_in(new_dir, "结构化数据.json"))
        old_modules, new_modules = _modules(old_doc), _modules(new_doc)
        for module_id in ("01", "03", "04"):
            if _score(old_modules[module_id]) != _score(new_modules[module_id]):
                score_changes.append({"sample": sample, "module_id": module_id, "old": _score(old_modules[module_id]), "new": _score(new_modules[module_id])})
        if _shadow(old_modules["03"]) != _shadow(new_modules["03"]):
            shadow_changes.append({"sample": sample, "old": _shadow(old_modules["03"]), "new": _shadow(new_modules["03"])})
        metric_changes.extend({"sample": sample, **row} for row in _common_metric_changes(old_modules, new_modules))

        user_docx = _json_in(new_dir, "用户精简版.docx"); doctor_docx = _json_in(new_dir, "医生详细版.docx")
        user_text, doctor_text = _text(user_docx), _text(doctor_docx)
        forbidden = [term for term in banned_all if term in user_text or term in doctor_text]
        forbidden.extend(term for term in banned_user if term in user_text)
        if forbidden:
            raise RuntimeError(f"{sample} DOCX泄露禁用词: {forbidden}")
        for module_id, (name, status, note) in FRONT5.items():
            coverage_rows.append({"样本": sample, "模块编号": module_id, "检测项目": name, "覆盖状态": status, "证据说明": note})

        gloss = next((args.candidate_root / sample / "02_油脂分泌倾向").glob("*/01_表面油光检测结果图.jpg"), None)
        vascular = args.candidate_root / sample / "05_血管样结构/05_血管样结构检测结果图.jpg"
        visual_rows.append({
            "样本": sample, "SurfaceGloss结果图存在": bool(gloss and gloss.is_file()),
            "Vascular结果图存在": vascular.is_file(),
            "自动状态": "auto_check_pass" if gloss and gloss.is_file() and vascular.is_file() else "needs_human_review",
        })

    regression = {
        "official_score_changes": len(score_changes), "official_score_change_details": score_changes,
        "shadow_score_changes": len(shadow_changes), "shadow_score_change_details": shadow_changes,
        "base_algorithm_metric_changes": len(metric_changes), "base_algorithm_metric_change_details": metric_changes,
        "locked_source_note": "Surface Gloss V3与Vascular V2.1候选源文件仅被读取，未重新运行或覆盖。",
    }
    if any(regression[key] != 0 for key in ("official_score_changes", "shadow_score_changes", "base_algorithm_metric_changes")):
        raise RuntimeError(f"评分或底层指标发生回归: {regression}")

    args.current.mkdir(parents=True, exist_ok=True)
    (args.current / "metric_regression_diff.json").write_text(json.dumps(regression, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    _write_csv(args.current / "13张前五项医生需求覆盖对照.csv", coverage_rows)
    _write_csv(args.current / "13张前五项视觉QC索引.csv", visual_rows)
    shutil.copy2(args.coverage_doc, args.current / args.coverage_doc.name)

    selected = {"visia示例图1.png", "visia示例图2.png", "visia示例图3.png", "样本03_909961_1.jpg", "样本09_889866_1.jpg", "样本10_1013197_1.jpg"}
    gloss_lines = ["# Surface Gloss V3视觉QC", "", "状态仅表示产物完整性；医学准确性仍需人工查看Overlay。", ""]
    vascular_lines = ["# Vascular V2.1视觉QC", "", "检查脸缘、发际线、眉眼、鼻孔、唇缘、毛发和皱纹误检。状态仅允许auto_check_pass或needs_human_review。", ""]
    for row in visual_rows:
        if row["样本"] in selected:
            gloss_lines.append(f"- {row['样本']}：{row['自动状态']}；重点查看局部镜面高光是否保留、Broad Sheen是否整片扩张。")
        vascular_lines.append(f"- {row['样本']}：{row['自动状态']}；仍需按八类误检区域人工复核。")
    (args.current / "SURFACE_GLOSS_V3_VISUAL_QC_20260810.md").write_text("\n".join(gloss_lines) + "\n", encoding="utf-8")
    (args.current / "VASCULAR_V21_VISUAL_QC_20260810.md").write_text("\n".join(vascular_lines) + "\n", encoding="utf-8")

    summary = [
        "# 前五项V0.1.2医学报告QC总结", "",
        "- 可见毛孔、综合色素V0.1.1、弥漫性泛红：保留正式人群分，分数零变化。",
        "- 综合色素V0.1.2：仅医生/内部Shadow对照，未晋升为生产分。",
        "- 油脂分泌倾向：展示Surface Gloss V3和紫质证据，暂不评分、无等级。",
        "- 血管样结构：展示V2.1候选检测结果，暂不评分、无等级。",
        "- 06～11、Worker合同、九项算法参数、ECDF配置均未修改。", "",
        f"- 评分回归：official={regression['official_score_changes']}，shadow={regression['shadow_score_changes']}，底层共同指标={regression['base_algorithm_metric_changes']}。",
    ]
    (args.current / "前五项V012医学报告QC总结.md").write_text("\n".join(summary) + "\n", encoding="utf-8")
    print(json.dumps({"samples": 13, **{key: regression[key] for key in ("official_score_changes", "shadow_score_changes", "base_algorithm_metric_changes")}}, ensure_ascii=False))


if __name__ == "__main__":
    main()

